# Slack Webhook URL을 환경변수에 설정
export SLACK_WEBHOOK_URL="https://hooks.slack.com/services/T00/B00/XXX"

# JSON 페이로드로 메시지 전송
curl -X POST "$SLACK_WEBHOOK_URL" \
  -H 'Content-Type: application/json' \
  -d '{
    "text": "빌드 성공",
    "blocks": [
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "*main* 브랜치 빌드가 완료되었습니다.\n커밋: `a1b2c3d`"
        }
      }
    ]
  }'
